sqlite3_exec(db, "PRAGMA journal_mode=WAL;", 0, 0, 0);
sqlite3_exec(db, "PRAGMA synchronous=FULL;", 0, 0, 0);
sqlite3_exec(db, "CREATE TABLE IF NOT EXISTS msg_store("
                 "id TEXT PRIMARY KEY, chan TEXT, ts INTEGER, body BLOB);", 0, 0, 0);
sqlite3_stmt *ins;                    /* prepared once, reused per message */
sqlite3_prepare_v2(db, "INSERT OR IGNORE INTO msg_store VALUES(?,?,?,?)", -1, &ins, 0);
sqlite3_bind_text(ins, 1, m->id, -1, SQLITE_STATIC);
sqlite3_bind_text(ins, 2, m->channel, -1, SQLITE_STATIC);
sqlite3_bind_int64(ins, 3, now_ms());
sqlite3_bind_blob(ins, 4, m->body, m->len, SQLITE_STATIC);
if (sqlite3_step(ins) != SQLITE_DONE) tap_drops++;  /* never fail the sender */
sqlite3_reset(ins);
